from pathlib import Path
import base64
import subprocess

BASE = "517c1f7c567f089d75bd8f0ab97942201ffc8490"
root = Path.cwd()

def dec(v):
    return base64.b64decode(v.encode("ascii")).decode("utf-8")

def fail(message):
    print(f"ERROR: {message}")
    raise SystemExit(1)

head = subprocess.check_output(
    ["git", "rev-parse", "HEAD"],
    cwd=root,
    text=True,
).strip()

if head != BASE:
    fail(
        f"This correction was built on pushed master {BASE}, "
        f"but local HEAD is {head}. No files were changed."
    )

paths = {
    "actions": root / "app/(portal)/game/breeze-lodgings-actions.ts",
    "access": root / "lib/breeze-lodgings/access.ts",
    "private_actions": root / "app/(portal)/private-location/actions.ts",
    "popup": root / "components/private-location/private-location-invitation-popup.tsx",
    "conversation": root / "app/(portal)/messages/[id]/components/ConversationMessageList.tsx",
}

for path in paths.values():
    if not path.exists():
        fail(f"Missing required file: {path.relative_to(root)}. No files were changed.")

texts = {k: p.read_text(encoding="utf-8") for k, p in paths.items()}

# Ensure the previous combined patch has actually been applied locally.
for anchor in [
    "withdrawBreezeLodgingInvitation",
    "breezeRental",
]:
    if anchor not in texts["actions"] and anchor not in texts["private_actions"]:
        fail(
            "The previous Breeze invitation/calendar patch does not appear to be applied locally. "
            "No files were changed."
        )

# Breeze actions: swap table names only in this file, change message marker,
# and insert dedicated response action before remove.
actions = texts["actions"]
if actions.count(dec("InByaXZhdGVfbG9jYXRpb25faW52aXRhdGlvbnMi")) < 3:
    fail("Expected Breeze invitation table references were not found. No files were changed.")
actions = actions.replace(
    dec("InByaXZhdGVfbG9jYXRpb25faW52aXRhdGlvbnMi"),
    dec("ImJyZWV6ZV9sb2RnaW5nX2ludml0YXRpb25zIg=="),
)
if dec("YDwhLS1QUklWQVRFX0xPQ0FUSU9OX0lOVklURToke2ludml0YXRpb24uaWR9LS0+YA==") not in actions:
    fail("Breeze PM marker anchor missing. No files were changed.")
actions = actions.replace(
    dec("YDwhLS1QUklWQVRFX0xPQ0FUSU9OX0lOVklURToke2ludml0YXRpb24uaWR9LS0+YA=="),
    dec("YDwhLS1CUkVFWkVfTE9ER0lOR19JTlZJVEU6JHtpbnZpdGF0aW9uLmlkfS0tPmA="),
    1,
)
remove = dec("ZXhwb3J0IGFzeW5jIGZ1bmN0aW9uIHJlbW92ZUJyZWV6ZUxvZGdpbmdHdWVzdCg=")
if actions.count(remove) != 1:
    fail("Breeze remove action anchor missing. No files were changed.")
actions = actions.replace(
    remove,
    dec(""),
    1,
)

# Add rental_id to invitation insert.
insert_old = """      .insert({
        room_id: roomId,
        inviter_character_id:
          characterId,"""
insert_new = """      .insert({
        rental_id: rental.id,
        room_id: roomId,
        inviter_character_id:
          characterId,"""
if actions.count(insert_old) != 1:
    fail("Breeze invitation insert anchor missing. No files were changed.")
actions = actions.replace(
    insert_old,
    insert_new,
    1,
)

# Private-location response: restore clean original behaviour.
private_actions = texts["private_actions"]
start = private_actions.find(dec("ZXhwb3J0IGFzeW5jIGZ1bmN0aW9uIHJlc3BvbmRQcml2YXRlTG9jYXRpb25JbnZpdGF0aW9uKAogIGZvcm1EYXRhOiBGb3JtRGF0YSwKKSB7"))
end = private_actions.find(dec("ZXhwb3J0IGFzeW5jIGZ1bmN0aW9uIGtpY2tQcml2YXRlTG9jYXRpb25NZW1iZXIo"))
if start < 0 or end < 0 or end <= start:
    fail("Private Location response function could not be located. No files were changed.")
private_actions = (
    private_actions[:start]
    + dec("")
    + private_actions[
        end + len(dec("ZXhwb3J0IGFzeW5jIGZ1bmN0aW9uIGtpY2tQcml2YXRlTG9jYXRpb25NZW1iZXIo")):
    ]
)

# Access loader: dedicated invitation table tied to current rental.
access = texts["access"]
old_access = dec("")
if access.count(old_access) != 1:
    fail("Breeze manage-data invitation query anchor missing. No files were changed.")
access = access.replace(
    old_access,
    dec(""),
    1,
)

# Popup full replacement. It intentionally supports both systems.
popup = dec("")

# Conversation list: add Breeze invitation card.
conversation = texts["conversation"]
old_import = dec("aW1wb3J0IHsgUHJpdmF0ZUxvY2F0aW9uSW52aXRhdGlvbk1lc3NhZ2UgfSBmcm9tICJAL2NvbXBvbmVudHMvbWVzc2FnZXMvcHJpdmF0ZS1sb2NhdGlvbi1pbnZpdGF0aW9uLW1lc3NhZ2UiOw==")
if conversation.count(old_import) != 1:
    fail("Conversation invitation import anchor missing. No files were changed.")
conversation = conversation.replace(
    old_import,
    dec("aW1wb3J0IHsgUHJpdmF0ZUxvY2F0aW9uSW52aXRhdGlvbk1lc3NhZ2UgfSBmcm9tICJAL2NvbXBvbmVudHMvbWVzc2FnZXMvcHJpdmF0ZS1sb2NhdGlvbi1pbnZpdGF0aW9uLW1lc3NhZ2UiOwppbXBvcnQgeyBCcmVlemVMb2RnaW5nSW52aXRhdGlvbk1lc3NhZ2UgfSBmcm9tICJAL2NvbXBvbmVudHMvbWVzc2FnZXMvYnJlZXplLWxvZGdpbmctaW52aXRhdGlvbi1tZXNzYWdlIjs="),
    1,
)
old_marker = dec("")
if conversation.count(old_marker) != 1:
    fail("Conversation invitation marker anchor missing. No files were changed.")
conversation = conversation.replace(
    old_marker,
    dec(""),
    1,
)

message_path = root / "components/messages/breeze-lodging-invitation-message.tsx"
if message_path.exists():
    fail(f"{message_path.relative_to(root)} already exists. No files were changed.")

# Final sanity.
if '"breeze_lodging_invitations"' not in actions:
    fail("Internal Breeze actions validation failed.")
if "breezeRental" in private_actions:
    fail("Private Location response was not cleanly restored.")
if "BREEZE_LODGING_INVITE" not in conversation:
    fail("Conversation marker validation failed.")

# Write only after all validation passes.
paths["actions"].write_text(actions, encoding="utf-8")
paths["access"].write_text(access, encoding="utf-8")
paths["private_actions"].write_text(private_actions, encoding="utf-8")
paths["popup"].write_text(popup, encoding="utf-8")
paths["conversation"].write_text(conversation, encoding="utf-8")
message_path.write_text(
    dec(""),
    encoding="utf-8",
)

print("Breeze invitation correction applied successfully.")
print("Changed files:")
for path in [
    paths["actions"],
    paths["access"],
    paths["private_actions"],
    paths["popup"],
    paths["conversation"],
    message_path,
]:
    print(" -", path.relative_to(root))
print()
print("IMPORTANT: run the supplied SQL in Supabase before testing invitations.")
